export const PortraitFontFaces=[{"family": "PCSlash", "weight": "400", "style": "normal", "source": "data:font/woff2;base64,"}, {"family": "PCWide", "weight": "700", "style": "normal", "source": "data:font/woff2;base64,"}, {"family": "PCSerif", "weight": "850", "style": "italic", "source": "data:font/woff2;base64,"}, {"family": "PCHand", "weight": "700", "style": "normal", "source": "data:font/woff2;base64,"}, {"family": "PCText", "weight": "650", "style": "normal", "source": "data:font/woff2;base64,"}];
let portraitFontReady;
export function loadPortraitFonts(){
 if(!portraitFontReady)portraitFontReady=Promise.all(PortraitFontFaces.map(item=>{
  const face=new FontFace(item.family,`url(${item.source})`,{weight:item.weight,style:item.style});
  return face.load().then(font=>document.fonts.add(font));
 }));return portraitFontReady;
}
